/**
 * Editor state and the changes that can be made to it. Ids are generated by
 * the caller and passed in, so the reducer stays pure.
 */
import type { QuestionType } from '@ludora/shared';
import { changeType, cloneQuestion, type DraftQuestion, type SetDetails } from './model.ts';

export interface EditorState {
  details: SetDetails;
  questions: DraftQuestion[];
  /** Question id to expanded. Missing means collapsed. */
  open: Record<string, boolean>;
}

export type EditorAction =
  | { type: 'details'; patch: Partial<SetDetails> }
  | { type: 'edit'; id: string; change: (q: DraftQuestion) => DraftQuestion }
  | { type: 'retype'; id: string; to: QuestionType }
  | { type: 'add'; question: DraftQuestion }
  | { type: 'duplicate'; id: string; newId: string }
  | { type: 'remove'; id: string }
  | { type: 'restore'; question: DraftQuestion; at: number }
  | { type: 'move'; id: string; by: number }
  | { type: 'toggle'; id: string; open?: boolean }
  | { type: 'openMany'; ids: string[] }
  | { type: 'setAllOpen'; open: boolean }
  | { type: 'import'; questions: DraftQuestion[]; mode: 'add' | 'replace'; details?: Partial<SetDetails>; open: boolean }
  | { type: 'reset'; state: EditorState };

function mapQuestion(state: EditorState, id: string, change: (q: DraftQuestion) => DraftQuestion): EditorState {
  let changed = false;
  const questions = state.questions.map((q) => {
    if (q.id !== id) return q;
    const next = change(q);
    if (next !== q) changed = true;
    return next;
  });
  return changed ? { ...state, questions } : state;
}

export function editorReducer(state: EditorState, action: EditorAction): EditorState {
  switch (action.type) {
    case 'details':
      return { ...state, details: { ...state.details, ...action.patch } };
    case 'edit':
      return mapQuestion(state, action.id, action.change);
    case 'retype':
      return mapQuestion(state, action.id, (q) => changeType(q, action.to));
    case 'add':
      return { ...state, questions: [...state.questions, action.question], open: { ...state.open, [action.question.id]: true } };
    case 'duplicate': {
      const at = state.questions.findIndex((q) => q.id === action.id);
      if (at < 0) return state;
      const questions = [...state.questions];
      questions.splice(at + 1, 0, cloneQuestion(state.questions[at]!, action.newId));
      return { ...state, questions, open: { ...state.open, [action.newId]: true } };
    }
    case 'remove': {
      const questions = state.questions.filter((q) => q.id !== action.id);
      if (questions.length === state.questions.length) return state;
      const open = { ...state.open };
      delete open[action.id];
      return { ...state, questions, open };
    }
    case 'restore': {
      if (state.questions.some((q) => q.id === action.question.id)) return state;
      const questions = [...state.questions];
      questions.splice(Math.min(action.at, questions.length), 0, action.question);
      return { ...state, questions, open: { ...state.open, [action.question.id]: true } };
    }
    case 'move': {
      const from = state.questions.findIndex((q) => q.id === action.id);
      const to = from + action.by;
      if (from < 0 || to < 0 || to >= state.questions.length) return state;
      const questions = [...state.questions];
      const [moved] = questions.splice(from, 1);
      questions.splice(to, 0, moved!);
      return { ...state, questions };
    }
    case 'toggle': {
      const open = action.open ?? !state.open[action.id];
      if (Boolean(state.open[action.id]) === open) return state;
      return { ...state, open: { ...state.open, [action.id]: open } };
    }
    case 'openMany': {
      if (action.ids.every((id) => state.open[id])) return state;
      const open = { ...state.open };
      for (const id of action.ids) open[id] = true;
      return { ...state, open };
    }
    case 'setAllOpen':
      return { ...state, open: Object.fromEntries(state.questions.map((q) => [q.id, action.open])) };
    case 'import': {
      const questions = action.mode === 'replace' ? action.questions : [...state.questions, ...action.questions];
      const open = action.mode === 'replace' ? {} : { ...state.open };
      for (const q of action.questions) open[q.id] = action.open;
      return { details: action.details ? { ...state.details, ...action.details } : state.details, questions, open };
    }
    case 'reset':
      return action.state;
  }
}
